def seed(apps, schema_editor):
    """Two departments and their sections exist from the start (everything else is made by voice). People whose
    old department text (or job) says so are put in them; every existing work item is filed by its words, else by
    the department of the person it is for."""
    User = apps.get_model("core", "User")
    Department = apps.get_model("core", "Department")
    Section = apps.get_model("core", "Section")
    SharedTask = apps.get_model("core", "SharedTask")
    made = {}
    for name, name_hi, colour, aliases in DEFAULTS:
        dept, _ = Department.objects.get_or_create(name=name, defaults={"name_hi": name_hi, "colour": colour, "aliases": aliases})
        section, _ = Section.objects.get_or_create(name=name, kind="WORK", owner=None,
                                                   defaults={"name_hi": name_hi, "colour": colour, "aliases": aliases, "department": dept})
        made[name] = (dept, section, aliases)
    for u in User.objects.filter(is_active=True).exclude(role__in=["MD", "PA", "MG"]):
        hay = f"{u.department} {u.job_title}".lower()
        for name, (dept, _section, aliases) in made.items():
            if name.lower() in hay or any(a in hay.split() for a in aliases if " " not in a):
                dept.members.add(u)
                if not u.department:
                    u.department = name
                    u.save(update_fields=["department"])
                break
    member_dept = {}
    for name, (dept, section, _aliases) in made.items():
        for u in dept.members.all():
            member_dept.setdefault(u.id, section)
    for t in SharedTask.objects.filter(section__isnull=True).iterator():
        text = f"{t.title} {t.description} {t.notes}".lower()
        best, best_hits = None, 0
        for name, (_dept, section, aliases) in made.items():
            hits = sum(1 for a in [name.lower()] + aliases if (a in text.split() if " " not in a else a in text))
            if hits > best_hits:
                best, best_hits = section, hits
        if best is None and t.assignee_user_id:
            best = member_dept.get(t.assignee_user_id)
        if best is not None:
            SharedTask.objects.filter(id=t.id).update(section=best)


